    protected void createGenModelAnnotations() {
        String source = "http://www.eclipse.org/emf/2002/GenModel";
        this.addAnnotation((ENamedElement)this.sdEClass, source, new String[]{"documentation", "This element is a \"Special Data\" element. By using this element it is possible to extend the dtd with a \"new\" element tag."});
        this.addAnnotation((ENamedElement)this.sdEClass.getEOperations().get(0), source, new String[]{"body", "return <%org.eclipse.sphinx.emf.util.EObjectUtil%>.getMixedText(getMixed());"});
        this.addAnnotation((ENamedElement)this.sdEClass.getEOperations().get(1), source, new String[]{"body", "<%org.eclipse.sphinx.emf.util.EObjectUtil%>.setMixedText(getMixed(), text);"});
        this.addAnnotation((ENamedElement)this.getSdgContents_Sds(), source, new String[]{"documentation", "This element is a \"Special Data\" element. By using this element it is possible to extend the dtd with a \"new\" element tag."});
        this.addAnnotation((ENamedElement)this.getSdgContents_Sdgs(), source, new String[]{"documentation", "<sdg> (Special Data Group) is a backdoor used to handle elements that has not yet been defined in a DTD. The <sdg> is a containder for one or several <sd> that defines new elements and carries the information. Special Data should only be used moderately since all elements should be defined in the dtd. Thereby should SDG be considered as a temporary sollution when elements are missing. If a <sdgCaption> element is created along with a <shortName> it is possible to reference the <sdg> structure via a <xref>."});
        this.addAnnotation((ENamedElement)this.sdgsEClass, source, new String[]{"documentation", "This is a container for one or several <sdg> (Special Data Group) elements.\r\n\r\nSpecial data groups (SDGs) are a standard extension mechanism for harmonized objects; they are used to store data for that no other element exists of the data model in a structured way. It could be considerd as a \"well formed island\" which allows to carry specific data even if the DTD itself does not expllicitly supports it. this prevents a process designer or a user to entirely switch to another technology if information musst be transferred whichis not explicitly supported."});
        this.addAnnotation((ENamedElement)this.getSdgs_Sdgs(), source, new String[]{"documentation", "<sdg> (Special Data Group) is a backdoor used to handle elements that has not yet been defined in a DTD. The <sdg> is a containder for one or several <sd> that defines new elements and carries the information. Special Data should only be used moderately since all elements should be defined in the dtd. Thereby should SDG be considered as a temporary sollution when elements are missing. If a <sdgCaption> element is created along with a <shortName> it is possible to reference the <sdg> structure via a <xref>."});
        this.addAnnotation((ENamedElement)this.sdgEClass, source, new String[]{"documentation", "<sdg> (Special Data Group) is a backdoor used to handle elements that has not yet been defined in a DTD. The <sdg> is a containder for one or several <sd> that defines new elements and carries the information. Special Data should only be used moderately since all elements should be defined in the dtd. Thereby should SDG be considered as a temporary sollution when elements are missing. If a <sdgCaption> element is created along with a <shortName> it is possible to reference the <sdg> structure via a <xref>."});
        this.addAnnotation((ENamedElement)this.getSdg_SdgCaption(), source, new String[]{"documentation", "This enables a <shortName> to be assigned to ID and enables a <longName> to be assigned to a special data group <sdg> ."});
    }

